"""Render persisted bounded hunter OFF/ON decisions from one frozen input."""
from collections import Counter
import json,html
from pathlib import Path
ROOT=Path('research/analyst_blindspot_hunter_20261014')
def name(p):return p.get('name',p.get('player_name',p['player_id']))
def signature(l):return tuple(sorted(str(p['player_id']) for p in l))
def total(l,k):return sum(float(p[k]) for p in l)
def main():
    results={a:json.loads((ROOT/(a+'_result.json')).read_text()) for a in ['off','on']};on=results['on'];engine=on['football_analyst'];hunter=engine['challenger'];req={a:json.loads((ROOT/(a+'_request.json')).read_text()) for a in results}
    for a in req:req[a]['optimizer'].pop('optimizer_run_id');req[a]['optimizer']['params'].pop('analyst_challenger_enabled')
    assert req['off']==req['on']
    for r in results.values():assert r['status']=='completed' and len(r['results'])==5 and r['entry_readiness']['entry_ready'] is False and r['preliminary_report']['snapshot_sha256']==req['on']['snapshot_sha256'] and r['football_analyst']['packet_sha256']==engine['packet_sha256']
    lookup={str(p['player_id']):p for r in results.values() for l in r['results'] for p in l};counts={a:Counter(str(p['player_id']) for l in r['results'] for p in l) for a,r in results.items()};changes=[];scores={}
    for i,l in enumerate(on['results'],1):
        ids=set(signature(l));old=max(enumerate(results['off']['results'],1),key=lambda item:len(ids&set(signature(item[1]))));before=set(signature(old[1]));changes.append(dict(on_slot=i,closest_off_slot=old[0],shared=len(ids&before),added=[name(lookup[p]) for p in sorted(ids-before)],removed=[name(lookup[p]) for p in sorted(before-ids)],base_mean=total(l,'projection'),salary=total(l,'salary'),idea_id=l[0]['analyst_allocated_idea_id'],challenger_id=l[0].get('analyst_challenger_vulnerability_id')))
    for a,r in results.items():scores[a]=[{w['scenario_id']:sum(w['moments'][str(p['player_id'])]['mean']+.35*(w['moments'][str(p['player_id'])]['p90']-w['moments'][str(p['player_id'])]['mean']) for p in l) for w in engine['scenario_definitions']} for l in r['results']]
    evidence=dict(classification='PRELIMINARY_RESEARCH',entry_ready=False,experiment_kind='generation_and_reallocation_comparison',identical_initial_pool=True,identical_final_pool=False,run_ids={a:r['job_id'] for a,r in results.items()},snapshot_sha256=req['on']['snapshot_sha256'],packet_sha256=engine['packet_sha256'],hunter=hunter,removed_off_slots=[i for i,l in enumerate(results['off']['results'],1) if signature(l) not in {signature(n) for n in on['results']}],new_on_slots=[i for i,l in enumerate(on['results'],1) if signature(l) not in {signature(n) for n in results['off']['results']}],roster_changes=changes,common_condition_scores=scores,exposures=[dict(player_id=p,player=name(lookup[p]),salary=lookup[p]['salary'],off=counts['off'][p],on=counts['on'][p]) for p in sorted(lookup,key=lambda p:(-max(counts[a][p] for a in counts),name(lookup[p])))],limitations=['Classic only, at most20 complete initial lineups; opt-in and off by default.','The saved model P10 is a downside stress endpoint combined with a sourced opposite script, not calibrated joint probability or a new factual injury/absence forecast.','Sourced football capability and conditional opportunities are incomplete; unsupported branches explicitly remain gaps.','One counter-state coverage improvement does not prove a profitable edge or comprehensive outcome diversity.','Opportunity cost includes displaced original game/script coverage; initial allocation and deliberate revision are preserved.'])
    (ROOT/'comparison.json').write_text(json.dumps(evidence,indent=2,allow_nan=False)+'\n')
    lines=['# Sunday Main: bounded blind-spot hunter OFF / ON','','**PRELIMINARY RESEARCH — not entry cleared.** Same frozen salary/projections/ownership, injury assumptions, sourced discovery packet and controls; only `analyst_challenger_enabled` differs. Discovery reservation remains enforced. Original CONSTRUCTION and all earlier comparisons remain preserved.','','## What the second search found','',f"Initial pool {hunter['initial_candidate_count']} distinct canonical rosters; selected {hunter['initial_selected_count']}. The hunter used {hunter['solver_calls']} targeted legal solve(s), admitted {hunter['accepted_candidate_count']} new roster(s), yielding pool {hunter['candidate_pool_count']}; final portfolio remains5. Status: {hunter['status']}. No95%screen, no relaxation and no forced weak challenger.",'','| Failure mode | Gap classification | Decision | Own-condition gain |','|---|---|---|---:|']
    for a in hunter['attempts']:lines.append(f"| {a['failure_mode']} | {a['classification']} | {a['status']}: {a['reason']} | {100*a['relative_coverage_gain']:.2f}% |" if 'relative_coverage_gain' in a else f"| {a['failure_mode']} | {a['classification']} | {a['status']}: {a['reason']} | — |")
    lines+=['','Puka appeared in every original candidate. A sourced Rams run-control alternative existed as a credible idea but had no constructed roster without that receiving dependency: a **generation gap**. The hunter searches that explicit opposite script, conserves target/carry volume through the declared20-unit shift, and tests Puka realizing his saved modeledP10 endpoint. This is an uncalibrated stress endpoint, not an absence assumption, predictive conditional distribution or probability estimate. The roster remains salary/position legal and player eligibility stays unchanged.','', 'Kyren downside already had a selected response: the Henry/Rodgers roster contains Rams receiving exposure without Kyren. Two Rams receivers can benefit from a passing script without requiring Stafford; a QB rule must not hide real outcome coverage. That existing state is included in the reallocation coverage audit without regeneration. Jaylen’s contrary team-passing idea lacks an admitted credible sourced branch, so it is explicitly unsupported; the hunter does not invent one.','',f"Sum of base projected means changes {hunter['initial_base_mean_sum']:.2f} → {hunter['selected_base_mean_sum']:.2f} ({hunter['selected_base_mean_sum']-hunter['initial_base_mean_sum']:+.2f}); this is central forecast bookkeeping, not EV or profit. Coverage objective {hunter['initial_coverage_objective']:.5f} → {hunter['selected_coverage_objective']:.5f} uses disclosed uncalibrated counter-state weight0.25; it cannot be compared to old solver scores.",'','## Actual saved portfolios',''];tables=[]
    for a,r in results.items():
        lines+=['### Hunter '+a.upper(),'',f"Saved run `{r['job_id']}`.",'','| # | QB | RB | WR | TE | DST | Salary | Base mean | Idea |','|---|---|---|---|---|---|---:|---:|---|'];trs=[]
        for i,l in enumerate(r['results'],1):
            cells=[str(i)]+[', '.join(name(p) for p in l if p['position']==pos) for pos in ['QB','RB','WR','TE','DST']]+[f"${total(l,'salary'):,.0f}",f"{total(l,'projection'):.2f}",l[0]['analyst_allocated_idea_id']];lines.append('| '+' | '.join(cells)+' |');trs.append('<tr>'+''.join('<td>'+html.escape(c)+'</td>' for c in cells)+'</tr>')
        lines.append('');tables.append('<h2>Hunter '+a.upper()+'</h2><div class="scroll"><table><tr>'+''.join('<th>'+h+'</th>' for h in ['#','QB','RB','WR','TE','DST','Salary','Base mean','Idea'])+'</tr>'+''.join(trs)+'</table></div>')
    lines+=['## Deliberate portfolio changes and inexpensive support','',f"Actual discarded OFF slots: {evidence['removed_off_slots']}; newly selected ON slots: {evidence['new_on_slots']}. Closest-roster comparisons below measure overlap and are not proof of replacement origin.",'']
    for c in changes:lines.append(f"- ON #{c['on_slot']} vs closest OFF #{c['closest_off_slot']}: {c['shared']}/9 shared; adds {', '.join(c['added']) or 'none'}; removes {', '.join(c['removed']) or 'none'}. Challenger lineage: {c['challenger_id'] or 'original candidate'}.")
    lines+=['','| Player | Salary | OFF /5 | ON /5 |','|---|---:|---:|---:|']
    for e in evidence['exposures']:lines.append(f"| {e['player']} | ${float(e['salary']):,.0f} | {e['off']} | {e['on']} |")
    lines+=['','## Individual selected player values','']
    for i,l in enumerate(on['results'],1):
        lines += [f'### ON lineup {i}','','| Position | Player | Team | Salary | Base projected mean |','|---|---|---|---:|---:|']
        for p in l:lines.append(f"| {p['position']} | {name(p)} | {p['player_team']} | ${float(p['salary']):,.0f} | {float(p['projection']):.2f} |")
        lines.append('')
    lines+=['## Limits and retained evidence','','The initial plan, added canonical candidate, accepted/rejected reasons, source/counterevidence, revised allocation and remaining dependence are saved. The new Rams run roster displaces the original New Orleans passing slot; this is a visible opportunity cost, not a claim that New Orleans is weak. Inexpensive player changes are conditional construction consequences, not independently proven matchup edges. Explicit user locks can leave an unavoidable blind spot. Maximum3 solver calls/6 audited failure modes/20-lineup portfolio; default2 calls/3 modes/20-second search budget. Captain-aware identity dedup is tested, but Showdown search is not implemented.','', 'All base player forecasts and source errors remain unchanged. Missing injury/practice evidence keeps final entry readiness false. No CSV export/submission; no calibrated forward performance or profit claim.','',f"Packet `{engine['packet_sha256']}`; snapshot `{req['on']['snapshot_sha256']}`.",'', '[Machine evidence](comparison.json) · [Independent checks](independent_verification.json) · [Preserved discovery comparison](../analyst_outlier_discovery_20261014/LINEUP_COMPARISON.md) · [Original/prior merged/scenario-first comparison](../scenario_first_sunday_main_20261014/LINEUP_COMPARISON.md)']
    (ROOT/'LINEUP_COMPARISON.md').write_text('\n'.join(lines)+'\n');(ROOT/'LINEUP_COMPARISON.html').write_text('<!doctype html><html><head><meta charset="utf-8"><title>Sunday bounded hunter comparison</title><style>body{font:15px system-ui;margin:24px;line-height:1.5}table{border-collapse:collapse}td,th{padding:10px;border:1px solid #ccc;vertical-align:top}.scroll{overflow:auto}</style></head><body><h1>Sunday bounded blind-spot hunter</h1><p><strong>PRELIMINARY RESEARCH — NOT ENTRY CLEARED</strong></p><p>Generation gap closed with one targeted opposite-script/downside challenger. Existing covered and unsupported states remain distinct.</p>'+''.join(tables)+'<p><a href="LINEUP_COMPARISON.md">Gap decisions, cheap supports and full review</a> · <a href="comparison.json">Machine evidence</a></p></body></html>');print(evidence['run_ids']);print(changes)
if __name__=='__main__':main()
